/// What the code generated for test classes (`<name>.test.spring.dart`,
/// from `@SpringBootTest` classes) uses; not meant to be imported by hand.
/// It is imported with a prefix, so its names never clash with the test
/// file's.
library;

export 'package:spring_boot_starter_test/spring_boot_starter_test.dart';
export 'package:test_api/scaffolding.dart'
    show group, setUp, setUpAll, tearDown, tearDownAll, test;
